import java.util.Scanner;

public class ClockAngles {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNext()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(" ");
            int h = Integer.parseInt(parts[0]);
            int m = Integer.parseInt(parts[1]);
            int s = Integer.parseInt(parts[2]);
            if (h == 0 && m == 0 && s == 0) break;

            double startSeconds = h * 3600.0 + m * 60.0 + s;
            double totalSeconds = startSeconds;
            boolean found = false;

            while (!found) {
                double hourAngle = (totalSeconds % 43200) * 0.008333333333333333; // 360/43200
                double minuteAngle = (totalSeconds % 3600) * 0.1; // 360/3600
                double secondAngle = (totalSeconds % 60) * 6.0; // 360/60

                double angleSM = Math.abs(secondAngle - minuteAngle);
                if (angleSM > 180) angleSM = 360 - angleSM;
                double angleSH = Math.abs(secondAngle - hourAngle);
                if (angleSH > 180) angleSH = 360 - angleSH;

                if (angleSM >= 1e-9 && angleSH >= 1e-9 && Math.abs(angleSM - angleSH) < 1e-9) {
                    int totalSec = (int) Math.round(totalSeconds);
                    int hours = (totalSec / 3600) % 24;
                    int minutes = (totalSec % 3600) / 60;
                    int seconds = totalSec % 60;
                    System.out.printf("%02d %02d %02d%n", hours, minutes, seconds);
                    found = true;
                }

                totalSeconds += 0.5; // step by 0.5 sec for precision
                if (totalSeconds > startSeconds + 43200) break; // avoid infinite loop
            }
        }
        sc.close();
    }
}

