public class Main {
    static final double EPS = 1e-10;

    // Normalize to [0, 360)
    static double norm(double x) {
        x %= 360.0;
        if (x < 0) x += 360.0;
        return x;
    }

    // Signed smallest difference a-b in (-180,180]
    static double diff180(double a, double b) {
        double d = norm(a - b);
        if (d > 180.0) d -= 360.0;
        return d;
    }

    // Check if at time t seconds from 00:00:00 the condition holds
    static boolean ok(double t) {
        double s = norm(6.0 * t);              // second hand
        double m = norm(0.1 * t);             // minute hand
        double h = norm(t / 120.0);           // hour hand

        // no overlaps
        if (Math.abs(diff180(s, m)) < 1e-8) return false;
        if (Math.abs(diff180(s, h)) < 1e-8) return false;
        if (Math.abs(diff180(m, h)) < 1e-8) return false;

        // second hand bisects the angle between minute and hour hands:
        // equal angles between second and minute/hour
        double d1 = Math.abs(diff180(s, m));
        double d2 = Math.abs(diff180(s, h));
        return Math.abs(d1 - d2) < 1e-8;
    }

    // Candidate times satisfy one of:
    // 2*S = M + H (mod 360)  or  2*S = M + H + 360 (mod 360)
    // With:
    // S = 6t, M = 0.1t, H = t/120
    // => (709/60)t = 360k   or   (709/60)t = 180 + 360k
    static double nextTime(double start) {
        double coef = 709.0 / 60.0;

        double[] shift = {0.0, 180.0};

        double best = Double.POSITIVE_INFINITY;

        for (double sh : shift) {
            // coef * t = sh + 360k
            double x = coef * start - sh;
            long k = (long)Math.floor(x / 360.0);
            for (long kk = Math.max(0, k - 2); kk <= k + 3; kk++) {
                double rhs = sh + 360.0 * kk;
                double t = rhs / coef;
                if (t + 1e-9 < start) continue;
                if (ok(t)) {
                    if (t < best) best = t;
                }
            }
            long kceil = (long)Math.ceil(x / 360.0);
            for (long kk = Math.max(0, kceil - 2); kk <= kceil + 3; kk++) {
                double rhs = sh + 360.0 * kk;
                double t = rhs / coef;
                if (t + 1e-9 < start) continue;
                if (ok(t)) {
                    if (t < best) best = t;
                }
            }
        }

        return best;
    }

    static String formatTime(double t) {
        // Round to nearest second for output
        long sec = Math.round(t);
        long h = sec / 3600;
        long m = (sec % 3600) / 60;
        long s = sec % 60;
        return String.format("%02d:%02d:%02d", h, m, s);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        StringBuilder out = new StringBuilder();

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;

            StringTokenizer st = new StringTokenizer(line, ": ");
            if (st.countTokens() < 3) continue;

            long hh = Long.parseLong(st.nextToken());
            long mm = Long.parseLong(st.nextToken());
            long ss = Long.parseLong(st.nextToken());

            if (hh == 0 && mm == 0 && ss == 0) break;

            double start = hh * 3600.0 + mm * 60.0 + ss;
            double ans = nextTime(start);
            out.append(formatTime(ans)).append('\n');
        }

        System.out.print(out.toString());
    }
}

