    cin.tie(nullptr);

    int h, m, s;
    char colon;

    while (cin >> h >> colon >> m >> colon >> s) {
        // Convert starting time to total seconds from 0:00:00
        double start_sec = h * 3600 + m * 60 + s;
        bool found = false;

        // We check up to 12 hours = 43200 seconds for periodicity.
        for (double t = start_sec; t < start_sec + 43200; t += 1e-3) {
            // angles in degrees
            double sec_angle = fmod(t * 6.0, 360.0);
            double min_angle = fmod(t * 0.1, 360.0);
            double hour_angle = fmod(t * (1.0/120.0), 360.0);

            // Check no two hands overlap: difference >= 1e-6
            double diff_sm = fabs(sec_angle - min_angle);
            double diff_sh = fabs(sec_angle - hour_angle);
            double diff_mh = fabs(min_angle - hour_angle);
            diff_sm = min(diff_sm, 360 - diff_sm);
            diff_sh = min(diff_sh, 360 - diff_sh);
            diff_mh = min(diff_mh, 360 - diff_mh);

            if (diff_sm < 1e-6 || diff_sh < 1e-6 || diff_mh < 1e-6)
                continue;

            // Check equality of angles between second hand and other two
            double ang1 = fmod(sec_angle - min_angle, 360);
            double ang2 = fmod(sec_angle - hour_angle, 360);
            if (ang1 < 0) ang1 += 360;
            if (ang2 < 0) ang2 += 360;
            // We compare the smaller angle
            ang1 = min(ang1, 360 - ang1);
            ang2 = min(ang2, 360 - ang2);

            if (fabs(ang1 - ang2) < 1e-6) {
                int total_sec = round(t);
                int hours = (total_sec / 3600) % 24;
                int minutes = (total_sec % 3600) / 60;
                int seconds = total_sec % 60;
                cout << setw(2) << setfill('0') << hours << ":"
                     << setw(2) << setfill('0') << minutes << ":"
                     << setw(2) << setfill('0') << seconds << "\n";
                found = true;
                break;
            }
        }

        if (!found) {
            // Should not happen per problem constraints, but handle gracefully
            cout << "00:00:00\n";
        }
    }

    return 0;
}

