using int64 = long long;

// We work in ticks of 1/11 second.
// Let n be the number of such ticks from time 0.
//
// Hand positions in "degrees * 120" units:
// second: 72n
// minute: 66n
// hour  : 11n
// (all modulo 43200)
//
// The condition "angles from second hand to minute/hour are equal"
// means the second hand is the angular bisector of the other two hands,
// i.e. on the circle:
//   2*S ≡ M + H (mod 43200)
// => 2*72n ≡ 66n + 11n (mod 43200)
// => 67n ≡ 0 (mod 43200)
// Since gcd(67,43200)=1, n ≡ 0 (mod 43200).
//
// So candidate times are exactly every 43200 ticks = 43200/11 seconds
// = 1 hour + 5/11 seconds.
//
// We also need no two hands overlap. At n multiple of 43200:
// second = 0, minute = 0, hour = 43200*k mod 43200 = 0.
// All three overlap, so such times are invalid.
//
// But the "equal angles" on a circle can also mean the smaller angles
// from second to minute and second to hour are equal, which happens when
// second is midpoint of the shorter arc OR the longer arc. Equivalently:
//   2*S ≡ M + H (mod 43200)   or   2*S ≡ M + H + 21600 (mod 43200)
// The first gives triple-overlap only, invalid.
// The second gives:
//   67n ≡ 21600 (mod 43200)
// Unique solution modulo 43200 because gcd(67,43200)=1.
//
// Compute inverse of 67 modulo 43200.

static int64 extgcd(int64 a, int64 b, int64 &x, int64 &y) {
    if (b == 0) {
        x = 1; y = 0;
        return a;
    }
    int64 x1, y1;
    int64 g = extgcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 x, y;
    extgcd(67, 43200, x, y);
    int64 inv67 = (x % 43200 + 43200) % 43200;

    // Base solution in ticks of 1/11 sec:
    // n0 ≡ 21600 * inv67 (mod 43200)
    int64 n0 = (21600LL * inv67) % 43200;

    // All valid times are n = n0 + 43200*k ticks.
    // Convert input time T = h:m:s to ticks threshold = ceil(11*T).
    // Since input is integer seconds, threshold = 11*T exactly.

    long long h, m, s;
    while (cin >> h >> m >> s) {
        long long totalSec = h * 3600LL + m * 60LL + s;
        long long need = totalSec * 11LL; // in ticks

        long long ansTicks;
        if (need <= n0) ansTicks = n0;
        else {
            long long k = (need - n0 + 43200 - 1) / 43200;
            ansTicks = n0 + k * 43200LL;
        }

        // ansTicks is in units of 1/11 sec.
        long long secPart = ansTicks / 11;
        int frac = (int)(ansTicks % 11); // fractional part = frac/11 sec

        long long oh = secPart / 3600;
        long long rem = secPart % 3600;
        long long om = rem / 60;
        long long os = rem % 60;

        cout << oh << ' '
             << setw(2) << setfill('0') << om << ' '
             << setw(2) << setfill('0') << os << ' '
             << frac << "/11\n";
    }

    return 0;
}

