#include <stdio.h>
#include <math.h>

#define EPS 1e-12

/*
We need the first time t >= given time such that:
1) second hand does not overlap minute hand or hour hand
2) the two angles between the second hand and the other two hands are equal

Let angles (degrees from 12 o'clock) be:
S = 6 t
M = 0.1 t
H = t / 120
where t is total seconds from some 12:00:00 reference, and angles are modulo 360.

"Two angles between the second hand and the other two hands are equal" means
the second hand is exactly on the angle bisector of minute and hour hands on the circle.
Thus, on the circle:
2S ≡ M + H (mod 360)

Substitute:
2*(6t) ≡ 0.1t + t/120 (mod 360)
12t ≡ 13t/120 (mod 360)
(1440t - 13t)/120 = 1427t/120 ≡ 0 (mod 360)

So:
1427 t ≡ 0 (mod 43200)

Since gcd(1427, 43200)=1, solutions are:
t = 43200*k / 1427   for integer k

These are all bisector times; among them, cases where S overlaps M or H must be excluded.
If S=M: 6t ≡ 0.1t (mod 360) => 59t ≡ 0 (mod 3600)
If S=H: 6t ≡ t/120 (mod 360) => 719t ≡ 0 (mod 43200)

Because t = 43200*k/1427 and 1427 is coprime with 59 and 719, overlap happens only when k is multiple of 1427,
i.e. every 43200 seconds (exactly at 12-hour boundaries). So we just skip those.

Input appears to be multiple datasets h m s, likely terminated by 0 0 0? But 0:0:0 is a valid time.
Commonly such problems terminate with -1 -1 -1. We'll support both EOF and negative sentinel.
We output absolute time (can exceed 12 hours), formatted HH:MM:SS with seconds rounded to nearest integer? 
However exact event times are generally fractional seconds. Such problems usually require hh:mm:ss with rounding to nearest second?
The statement says "specified format" but omitted here. We'll output H M S as hh:mm:ss with zero-padded 2-digit fields and integer seconds,
using nearest second carrying properly. This is the standard for this classic clock problem.

To avoid ambiguity, compute next k such that t_k >= input_seconds.
Then if k % 1427 == 0, increment k.
Answer time is absolute seconds from time 0, not modulo 12h, since clock can exceed 12 hours.
We need first event on or after given absolute time T where T = h*3600+m*60+s.

For rounding to nearest second in output:
ans_sec = floor(t + 0.5)
Then format with hours possibly >99? use at least 2 digits, but %02lld works for larger too.
*/

static long long gcdll(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main(void) {
    long long h, m, s;
    const long long DEN = 1427;
    const long long NUM = 43200; /* t_k = NUM * k / DEN */

    while (scanf("%lld %lld %lld", &h, &m, &s) == 3) {
        if (h < 0 || m < 0 || s < 0) break;

        long long T = h * 3600LL + m * 60LL + s;

        /* smallest k with NUM*k/DEN >= T  => k >= T*DEN/NUM */
        long long k = (T * DEN + NUM - 1) / NUM;

        /* exclude overlap cases: exactly when k is multiple of 1427 */
        if (k % DEN == 0) k++;

        double t = (double)NUM * (double)k / (double)DEN;

        /* round to nearest second for output */
        long long out = (long long)floor(t + 0.5 + EPS);

        long long oh = out / 3600;
        long long om = (out % 3600) / 60;
        long long os = out % 60;

        printf("%02lld:%02lld:%02lld\n", oh, om, os);
    }

    return 0;
}
